actions.action:
zl_proces: f.zl_proces, zl_pridelene: f.zl_pridelene, zl_authority: f.zl_authority,
poz_pridelene: f.poz_pridelene, poz_historia: f.poz_historia;

change zl_proces options { processOptions() }
change zl_authority options { authorityOptions() }
change zl_authority value { ["ROLE_USER"] }
change zl_pridelene value { "(nothing yet)" }
change poz_pridelene value { "(nothing yet)" }
change poz_historia value { "(no invitation yet)" }
changeCaseProperty("title").about { "New user" }
changeCaseProperty("color").about { "blue" }

document.function:
{ def hodnota ->
    def mail = ((hodnota ?: "") as String).trim()
    return mail ==~ /^[^@\s]+@[^@\s.]+\.[^@\s]{2,}$/
}

{ def pole ->
    def raw = pole.value
    if (raw == null) return []
    if (raw instanceof Collection) return raw.collect { it as String }
    if (raw.hasProperty("value") && raw.value instanceof Collection) {
        return raw.value.collect { it as String }
    }
    def s = (raw as String).trim()
    return s ? [s] : []
}

{ def zl_zoznam ->
    def out = []
    ((zl_zoznam.value ?: "") as String).split("\n").each { String riadok ->
        def r = riadok.trim()
        if (!r) return
        def casti = r.split("\\|", -1)
        if (casti.length < 2) return
        out << [rola: casti[0], siet: casti[1], verzia: (casti.length > 2 ? casti[2] : "vsetky")]
    }
    return out
}

{ def polozky ->
    if (!polozky) return "(nothing yet)"
    return polozky.collect { p ->
        def v = (p.verzia == null || p.verzia == "" || p.verzia == "vsetky")
                ? "all versions" : ("verzia " + (p.verzia as String).replace("_", "."))
        return "• " + p.rola + " — " + p.siet + " (" + v + ")"
    }.join("\n")
}

{ ->
    // Množina `pu_userid`, ktoré už majú prípad — načítaná JEDNÝM prechodom.
    // `findCases { it.dataSet... }` nefunguje (petriflow_reference, gotcha 40),
    // takže sa filtruje v Groovy.
    //
    // Pôvodne to bola funkcia `pripad_uctu(id)` volaná pre každý účet, čo je
    // jeden úplný prechod prípadmi na účet. Spolu s vtedy kvadratickým
    // `userSnapshot` na tom zosúladenie vytimeoutovalo.
    def out = [] as Set
    findCases({ it.processIdentifier.eq("admin/pouzivatelia/pu_pouzivatel") }).each {
        def v = ((it.getFieldValue("pu_userid") ?: "") as String).trim()
        if (v) out << v
    }
    return out
}

{ ->
    // Kto pozvanku poslal. `?.` chrani pred null, nie pred chybajucou property,
    // preto `hasProperty` - `UserFieldValue` a `IUser` sa v tomto lisia
    // a rozdiel sa prejavi az za behu uprostred akcie.
    def u = loggedUser()
    if (u == null) return "(unknown)"
    return (u.hasProperty("email") && u.email) ? (u.email as String) : (u.stringId as String)
}

{ def poz_historia, def riadok ->
    // Pripise zaznam NA ZACIATOK - kto pult otvori, ma poslednu pozvanku
    // v prvom riadku a nemusi rolovat.
    //
    // Strop je tu zamerne: pole je sucastou `dataSet` casu a ten sa cely cita
    // aj zapisuje pri kazdej zmene. Bez stropu by pult po roku prevadzky nosil
    // niekolko stotisic znakov v kazdej odpovedi `GET /api/task/{id}/data`.
    // Uplny zoznam pozvanych nie je toto pole - su to PRIPADY UCTOV, kde kazdy
    // pozvany clovek ma svoj a da sa podla stavu filtrovat.
    def limit = 100
    def stare = ((poz_historia.value ?: "") as String).split("\n").findAll { it.trim() }
    def vsetky = ([riadok as String] + (stare as List)).take(limit)
    if (stare.size() + 1 > limit) {
        vsetky = vsetky.take(limit - 1) + ["... older entries are on the Users card"]
    }
    return vsetky.join("\n")
}

{ def id ->
    // Prípad účtu.
    // Stačí zviazať. Meno, e-mail, oprávnenia aj role si prípad dotiahne z účtu
    // sám - má na to dátovú udalosť na `pu_userid`. Účet je zdroj pravdy.
    def c = createCase("admin/pouzivatelia/pu_pouzivatel")
    setData("t_pu_uprava", c, ["pu_userid": ["value": id as String, "type": "text"]])
    return c
}

actions.action:
zl_proces: f.zl_proces, zl_roly: f.zl_roly, zl_verzia: f.zl_verzia;

def siet = (zl_proces.value ?: "") as String
change zl_roly options { processRoleOptions(siet) }
change zl_roly value { [] }
change zl_verzia options { processVersionOptions(siet) }
change zl_verzia value { "vsetky" }

zl_proces: f.zl_proces, zl_roly: f.zl_roly, zl_verzia: f.zl_verzia,
zl_zoznam: f.zl_zoznam, zl_pridelene: f.zl_pridelene;

def siet = (zl_proces.value ?: "") as String
def verzia = ((zl_verzia.value ?: "vsetky") as String)
def vybrane = ako_zoznam(zl_roly)
if (siet && vybrane) {
    def riadky = rozbor_zoznamu(zl_zoznam).collect { it.rola + "|" + it.siet + "|" + it.verzia }
    vybrane.each { String rola ->
        def r = rola + "|" + siet + "|" + verzia
        if (!riadky.contains(r)) { riadky << r }
    }
    change zl_zoznam value { riadky.join("\n") }
    change zl_roly value { [] }
}
change zl_pridelene value { popis_zoznamu(rozbor_zoznamu(zl_zoznam)) }

zl_zoznam: f.zl_zoznam, zl_pridelene: f.zl_pridelene;

change zl_zoznam value { "" }
change zl_pridelene value { "(nothing yet)" }

zl_vysledok: f.zl_vysledok;

// Ucty vznikaju aj mimo tejto appky. Tlacidlo im doplni pripad; je idempotentne.
def pridane = []
def uz = 0
def maju = zviazane_ucty()
userOptions().each { String id, String popis ->
    if (maju.contains(id)) { uz++; return }
    def snap = userSnapshot(id)
    if (!snap || !snap.email) return
    zaloz_pripad(id)
    pridane << (snap.email as String)
}
change zl_vysledok value {
    "Account reconciliation:\n" +
    "- already had a case: " + uz + "\n" +
    (pridane ? ("- case added (" + pridane.size() + "): " + pridane.join(", "))
             : "- nothing needed adding")
}

zl_proces: f.zl_proces;

// Pri kazdom otvoreni znova - inak by novo naimportovana appka v ponuke nebola.
change zl_proces options { processOptions() }
change zl_authority options { authorityOptions() }

zl_email: f.zl_email, zl_heslo: f.zl_heslo, zl_authority: f.zl_authority;

def mail = ((zl_email.value ?: "") as String).trim()
if (!je_email(mail)) {
    throw new java.lang.IllegalStateException("The e-mail is not a valid address: " + mail)
}
if (findUserByEmail(mail) != null) {
    throw new java.lang.IllegalStateException("A user with the e-mail " + mail + " already exists.")
}
if (!registrationService.isPasswordSufficient(formPassword(zl_heslo.value))) {
    throw new java.lang.IllegalStateException("The password does not meet this instance's requirements.")
}
if (!ako_zoznam(zl_authority).contains("ROLE_USER")) {
    throw new java.lang.IllegalStateException(
            "Without ROLE_USER the person can log in but will see no views at all.")
}

zl_meno: f.zl_meno, zl_priezvisko: f.zl_priezvisko, zl_email: f.zl_email,
zl_heslo: f.zl_heslo, zl_authority: f.zl_authority, zl_zoznam: f.zl_zoznam,
zl_pridelene: f.zl_pridelene, zl_vysledok: f.zl_vysledok, zl_proces: f.zl_proces,
zl_roly: f.zl_roly, zl_verzia: f.zl_verzia;

def mail = ((zl_email.value ?: "") as String).trim()
def meno = ((zl_meno.value ?: "") as String).trim()
def priezvisko = ((zl_priezvisko.value ?: "") as String).trim()
def authorities = ako_zoznam(zl_authority)

def novy = createNewUser(meno, priezvisko, mail, formPassword(zl_heslo.value), authorities)
def id = novy.stringId as String
def riadky = ["account created: " + mail,
              "system authorities: " + (authorities ? authorities.join(", ") : "none")]

def pridelene = []
def zlyhane = []
rozbor_zoznamu(zl_zoznam).each { p ->
    if (setProcessRole(id, p.rola as String, p.siet as String, p.verzia as String, true)) {
        pridelene << (p.rola + " (" + p.siet + ")")
    } else {
        zlyhane << (p.rola + " (" + p.siet + ")")
    }
}
riadky << (pridelene ? "process roles: " + pridelene.join(", ") : "process roles: none")
if (zlyhane) {
    riadky << ("COULD NOT assign: " + zlyhane.join(", "))
}

// Ucet je entita - dostane vlastny pripad. Jeden ucet, jeden pripad.
def c = zaloz_pripad(id)
riadky << ("account case: " + c.stringId)

// Pult sa vyprazdni a je pripraveny na dalsi ucet. Bez tohto by tu zostali
// vypisane data predchadzajuceho cloveka - a heslo medzi nimi.
change zl_meno value { "" }
change zl_priezvisko value { "" }
change zl_email value { "" }
change zl_heslo value { "" }
change zl_authority value { ["ROLE_USER"] }
change zl_proces value { "" }
change zl_roly value { [] }
change zl_verzia value { "" }
change zl_zoznam value { "" }
change zl_pridelene value { "(nothing yet)" }
change zl_vysledok value { riadky.join("\n") }

changeCaseProperty("title").about { "New user" }

poz_proces: f.poz_proces, poz_roly: f.poz_roly, poz_verzia: f.poz_verzia;

def siet = (poz_proces.value ?: "") as String
change poz_roly options { processRoleOptions(siet) }
change poz_roly value { [] }
change poz_verzia options { processVersionOptions(siet) }
change poz_verzia value { "vsetky" }

poz_proces: f.poz_proces, poz_roly: f.poz_roly, poz_verzia: f.poz_verzia,
poz_zoznam: f.poz_zoznam, poz_pridelene: f.poz_pridelene;

def siet = (poz_proces.value ?: "") as String
def verzia = ((poz_verzia.value ?: "vsetky") as String)
def vybrane = ako_zoznam(poz_roly)
if (siet && vybrane) {
    def riadky = rozbor_zoznamu(poz_zoznam).collect { it.rola + "|" + it.siet + "|" + it.verzia }
    vybrane.each { String rola ->
        def r = rola + "|" + siet + "|" + verzia
        if (!riadky.contains(r)) { riadky << r }
    }
    change poz_zoznam value { riadky.join("\n") }
    change poz_roly value { [] }
}
change poz_pridelene value { popis_zoznamu(rozbor_zoznamu(poz_zoznam)) }

poz_zoznam: f.poz_zoznam, poz_pridelene: f.poz_pridelene;

change poz_zoznam value { "" }
change poz_pridelene value { "(nothing yet)" }

poz_email: f.poz_email, poz_proces: f.poz_proces, poz_roly: f.poz_roly,
poz_verzia: f.poz_verzia, poz_zoznam: f.poz_zoznam, poz_pridelene: f.poz_pridelene,
poz_vysledok: f.poz_vysledok, poz_historia: f.poz_historia;

def mail = ((poz_email.value ?: "") as String).trim()
def ked = java.time.LocalDateTime.now().format(
        java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm"))
def kto = kto_posiela()

// `pozvi` uz overuje tvar e-mailu, existujuci aktivny ucet aj SMTP a vracia
// vetu. Preto sa tu NEHADZE vynimka: z datoveho tlacidla by odmietnutie
// skoncilo ako chyba requestu, nie ako sprava vo formulari - a spravca by sa
// nedozvedel, co ma opravit.
def v = pozvi(mail)

if (!v.ok) {
    // Formular sa ZAMERNE nevyprazdni - je co opravit a poslat znova.
    change poz_vysledok value { v.sprava as String }
    change poz_historia value {
        do_historie(poz_historia, ked + " · " + (mail ?: "(bez adresy)") +
                " - NOT SENT: " + (v.sprava as String) + " · " + kto)
    }
    return
}

def id = v.userId as String
def riadky = [v.sprava as String,
              "the account is INVITED - they set their own name and password"]

def pridelene = []
def zlyhane = []
rozbor_zoznamu(poz_zoznam).each { p ->
    if (setProcessRole(id, p.rola as String, p.siet as String, p.verzia as String, true)) {
        pridelene << (p.rola + " (" + p.siet + ")")
    } else {
        zlyhane << (p.rola + " (" + p.siet + ")")
    }
}
riadky << (pridelene ? "process roles: " + pridelene.join(", ") : "process roles: none")
if (zlyhane) {
    riadky << ("COULD NOT assign: " + zlyhane.join(", "))
}

// Ucet je entita - dostane vlastny pripad, rovnako ako pri zakladani s heslom.
// PODMIENENE: opakovana pozvanka (vyprsany odkaz) bezi na uz existujucom ucte,
// ktory pripad uz ma; bez tejto kontroly by vznikol druhy a padol by invariant
// "jeden ucet = jeden pripad", ktory strazi `pucheck.py`.
if (zviazane_ucty().contains(id)) {
    riadky << "the account case already existed"
} else {
    def c = zaloz_pripad(id)
    riadky << ("account case: " + c.stringId)
}

// Hladanie v texte spravy je krehke - keby sa veta v `pozvi` preformulovala,
// historia by ticho prestala rozlisovat opakovane poslanie. Drzi to tu preto,
// ze `pozvi` iny priznak nevracia; ked bude treba, doplni sa do mapy.
def opakovane = ((v.sprava as String).contains("sent again"))
change poz_historia value {
    do_historie(poz_historia, ked + " · " + mail +
            (opakovane ? " - SENT AGAIN" : " - invited") +
            " - roles: " + (pridelene ? pridelene.join(", ") : "none") +
            " · " + kto)
}

change poz_email value { "" }
change poz_proces value { "" }
change poz_roly value { [] }
change poz_verzia value { "" }
change poz_zoznam value { "" }
change poz_pridelene value { "(nothing yet)" }
change poz_vysledok value { riadky.join("\n") }

poz_proces: f.poz_proces;

// Pri kazdom otvoreni znova - novo naimportovana appka by inak v ponuke nebola.
// A v `create` udalosti pripadu sa `change ... options` NEUCHOVA (LEARNINGS B11),
// takze toto je jedine miesto, kde ich nastavit ma zmysel.
change poz_proces options { processOptions() }
